\documentclass[border=5mm]{standalone} 
\usepackage{pgfplots}
\usepackage{amsmath}
\usepackage{tikz}
\begin{document}
	\pagestyle{empty} %% IMPORTANT
	\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
	\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
	\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
	\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
	\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
	\definecolor{rustred}{rgb}{0.784,0.392,0.149}
	\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}
\begin{tikzpicture}
\begin{axis}[
	tick style={draw=black, thick},
	tick label style={font=\footnotesize},
	label style={font=\small},
	legend style={font=\footnotesize},
	tick style={draw=black},
	axis line style = thick,
	axis y line = center,
	axis x line = middle,
	axis equal,
	xmin = -5, xmax = 5, 
	ymin = -5, ymax = 5, 
	xtick = {0}, %xticklabels={},
	ytick = {0}, %yticklabels={},
%	x tick label style={xshift={(\tick==4)*4pt}},
	xlabel = {$u$}, ylabel = {$v$},
	xlabel style={right},
	ylabel style={above}
	]

\draw[fill=deepskyblue, fill opacity=0.2, line width=1.2pt, draw=none, dashed] plot[domain=-20:-0.1, samples=200] (axis cs:\x,{1/\x}) -- (current page.south west) -- (axis cs: 0,-20) -- (axis cs: 0,20) -- cycle;
\plot[domain=-10:-0.1, samples=200, line width=1.2pt, draw=deepskyblue, dashed] {1/x};

\draw[fill=deepskyblue, fill opacity=0.2, line width=1.2pt, draw=deepskyblue, dashed] plot[domain=0.1:10, samples=200] (axis cs:\x,{1/\x}) -- (current page.north east) --cycle;
 	\node[above right] at (axis cs:1,1) {$\displaystyle v=\frac{1}{u}$};

	%Ancors:
	%(current page.north east) 
	%(current page.south east) 
	%(current page.south west) 
	%(current page.north west) 

\end{axis}
\end{tikzpicture}
\end{document}

