	xlabel = {$u$}, ylabel = {$v$},
	xlabel style={right},
	ylabel style={above}
	]

	\draw[fill=deepskyblue, fill opacity=0.2, line width=1.2pt, draw=deepskyblue, dashed] 
		plot[domain=-10:10, samples=200]
			(axis cs:\x,{(-1)*\x}) -- (current page.south west) -- cycle;  
